import fs from 'node:fs';
import path from 'node:path';
import { isTestOrDocFile } from './rules/builtin.js';
import { getBatchGitFiles } from '../lib/git.js';

/**
 * Checks whether a file is an auto-generated asset by inspecting standard path conventions
 * and header comments. Requires matching standard generated file paths or historical presence in baseRef
 * to prevent gaming/bypass on arbitrary source files.
 */
export function isGeneratedFile(filePath, content, oldContent = null) {
  if (content === undefined && typeof filePath === 'string') {
    content = filePath;
    filePath = '';
  }
  if (!content && !oldContent) return false;
  const norm = String(filePath || '').replace(/\\/g, '/');

  const checkMarker = (text) => {
    if (!text || typeof text !== 'string') return false;
    const lines = text.slice(0, 2048).split('\n', 15);
    const pattern = /(?:\/\/|#|\/\*)\s*(?:code generated|generated by|autogenerated|auto-generated).*?(?:do not edit|never edit)/i;
    return lines.some((l) => pattern.test(l));
  };

  const hasMarker = checkMarker(content);
  const hadMarkerInBase = checkMarker(oldContent);

  // Path convention check: prevent gaming where developer puts marker in arbitrary source file
  const matchesGeneratedPath = /(?:\.pb\.go$|_gen\.go$|\.generated\.[a-z0-9]+$|\/(?:generated|autogen|gen|dist|build)\/)/i.test(norm);

  // Only allow exclusion if it matches generated path conventions OR was already generated in base
  return (matchesGeneratedPath && hasMarker) || hadMarkerInBase;
}

/**
 * Scans third-party framework imports / using directives (Layer 1).
 */
export function scanImports(filePath, content) {
  if (!content || typeof content !== 'string') return null;
  const norm = filePath.replace(/\\/g, '/');
  const ext = path.extname(norm).toLowerCase();

  // 1. Java / Kotlin
  if (['.java', '.kt'].includes(ext)) {
    // Security (L3)
    const javaSecRegex = /\bimport\s+(?:org\.springframework\.security|cn\.dev33\.satoken|org\.apache\.shiro|io\.jsonwebtoken|com\.auth0\.jwt|io\.quarkus\.security|io\.quarkus\.vertx\.http\.runtime\.security|io\.smallrye\.jwt|io\.ktor\.server\.auth)\b/;
    const javaFilterRegex = /\b(?:extends\s+OncePerRequestFilter|implements\s+(?:HandlerInterceptor|GlobalFilter|HttpAuthenticationMechanism))\b/;
    if (javaSecRegex.test(content) || javaFilterRegex.test(content)) {
      return { level: 'L3', id: 'SEM_JAVA_SECURITY', summary: `Java/Kotlin security framework import/filter in ${norm}`, mandatoryHumanReview: true };
    }

    // Server Contract / RPC / Messaging (L2)
    const javaContractRegex = /\bimport\s+(?:org\.apache\.dubbo|com\.alibaba\.dubbo|org\.apache\.rocketmq|com\.aliyun\.openservices\.ons|org\.springframework\.cloud\.openfeign|org\.springframework\.kafka|org\.springframework\.amqp|jakarta\.jms|jakarta\.ws\.rs|javax\.ws\.rs|io\.quarkus\.vertx\.web|io\.ktor\.server\.routing|com\.alibaba\.csp\.sentinel|io\.seata)\b/;
    const javaAnnotationRegex = /@(?:DubboService|DubboReference|FeignClient|RestController|RequestMapping|GetMapping|PostMapping|PutMapping|DeleteMapping|PatchMapping|Path)\b/;
    if (javaContractRegex.test(content) || javaAnnotationRegex.test(content)) {
      return { level: 'L2', id: 'SEM_JAVA_CONTRACT', summary: `Java/Kotlin server RPC/endpoint contract in ${norm}` };
    }

    // Persistence / Entity (L2)
    const javaDbRegex = /\bimport\s+(?:jakarta\.persistence|javax\.persistence|org\.jetbrains\.exposed\.sql|io\.quarkus\.hibernate\.orm\.panache)\b/;
    if (javaDbRegex.test(content) || /@(?:Entity|Table|TableName)\b/.test(content)) {
      return { level: 'L2', id: 'SEM_JAVA_PERSISTENCE', summary: `Java/Kotlin DB persistence entity in ${norm}` };
    }
  }

  // 2. Go
  if (ext === '.go') {
    // Security (L3)
    const goSecRegex = /"(?:github\.com\/golang-jwt\/jwt(?:\/v\d+)?|github\.com\/casbin\/casbin(?:\/v\d+)?|golang\.org\/x\/oauth2|github\.com\/coreos\/go-oidc|golang\.org\/x\/crypto)\b/;
    if (goSecRegex.test(content)) {
      return { level: 'L3', id: 'SEM_GO_SECURITY', summary: `Go security/auth package import in ${norm}`, mandatoryHumanReview: true };
    }

    // Server Contract (L2)
    const goContractRegex = /"(?:github\.com\/gin-gonic\/gin|github\.com\/labstack\/echo(?:\/v\d+)?|github\.com\/go-chi\/chi(?:\/v\d+)?|github\.com\/gofiber\/fiber(?:\/v\d+)?|github\.com\/cloudwego\/hertz|github\.com\/go-kratos\/kratos(?:\/v\d+)?|google\.golang\.org\/grpc|github\.com\/cloudwego\/kitex)\b/;
    if (goContractRegex.test(content) || /\b(?:http\.HandleFunc|http\.NewServeMux)\b/.test(content)) {
      return { level: 'L2', id: 'SEM_GO_CONTRACT', summary: `Go server HTTP/gRPC routing in ${norm}` };
    }

    // DB Migration (L2)
    const goDbRegex = /"(?:github\.com\/golang-migrate\/migrate(?:\/v\d+)?|github\.com\/pressly\/goose(?:\/v\d+)?|entgo\.io\/ent)\b/;
    if (goDbRegex.test(content) || /\bAutoMigrate\s*\(/.test(content)) {
      return { level: 'L2', id: 'SEM_GO_MIGRATION', summary: `Go database migration/schema in ${norm}` };
    }
  }

  // 3. Python
  if (ext === '.py') {
    // Security (L3)
    const pySecRegex = /\b(?:from\s+fastapi\.security\b|import\s+fastapi\.security\b|from\s+jose\b|import\s+jose\b|from\s+passlib\b|import\s+passlib\b|from\s+authlib\b|import\s+authlib\b|from\s+django\.contrib\.auth\b|from\s+rest_framework\.permissions\b|from\s+flask_login\b|import\s+bcrypt\b|import\s+jwt\b)/;
    if (pySecRegex.test(content)) {
      return { level: 'L3', id: 'SEM_PY_SECURITY', summary: `Python security framework import in ${norm}`, mandatoryHumanReview: true };
    }

    // Alembic / Django migrations
    const pyMigrateRegex = /\b(?:from\s+alembic\s+import\s+op|from\s+django\.db\s+import\s+migrations)\b/;
    if (pyMigrateRegex.test(content)) {
      const isDestructive = /(?:op\.drop_|DeleteModel|RemoveField)/.test(content);
      if (isDestructive) {
        return { level: 'L3', id: 'SEM_PY_DESTRUCTIVE_MIGRATION', summary: `Python destructive database migration in ${norm}`, mandatoryHumanReview: true };
      }
      return { level: 'L2', id: 'SEM_PY_MIGRATION', summary: `Python database migration in ${norm}` };
    }

    // Server Contract (L2)
    const pyContractRegex = /\b(?:from\s+django\.urls\b|from\s+rest_framework\b.*import\s+(?:APIView|ViewSet|Serializer)|from\s+airflow\b|from\s+celery\b)/;
    const hasFastApiFlask = /\b(?:import\s+(?:fastapi|flask)|from\s+(?:fastapi|flask)\b)/.test(content) &&
      /@\w+\.(?:route|get|post|put|delete|patch)\s*\(/.test(content);
    if (pyContractRegex.test(content) || hasFastApiFlask) {
      return { level: 'L2', id: 'SEM_PY_CONTRACT', summary: `Python server routing/contract in ${norm}` };
    }
  }

  // 4. Node.js / TypeScript
  if (['.js', '.jsx', '.ts', '.tsx', '.mjs', '.cjs'].includes(ext)) {
    // Security (L3) - Next.js root or src/ middleware
    if (/^(?:src\/)?middleware\.(?:ts|js)$/i.test(norm)) {
      return { level: 'L3', id: 'SEM_NODE_MIDDLEWARE', summary: `Next.js root middleware in ${norm}`, mandatoryHumanReview: true };
    }
    const nodeSecRegex = /\b(?:from\s+['"](?:passport|@nestjs\/passport|@nestjs\/jwt|jose|jsonwebtoken|next-auth|@auth\/core|better-auth|bcrypt|argon2)['"]|require\(['"](?:passport|@nestjs\/passport|@nestjs\/jwt|jose|jsonwebtoken|next-auth|@auth\/core|better-auth|bcrypt|argon2)['"]\))/;
    if (nodeSecRegex.test(content)) {
      return { level: 'L3', id: 'SEM_NODE_SECURITY', summary: `Node.js security package import in ${norm}`, mandatoryHumanReview: true };
    }

    // Server Contract (L2)
    const nodeContractRegex = /\b(?:from\s+['"](?:express|fastify|koa|hono|@trpc\/server|@apollo\/server|@nestjs\/graphql|graphql-yoga)['"]|require\(['"](?:express|fastify|koa|hono|@trpc\/server|@apollo\/server|@nestjs\/graphql|graphql-yoga)['"]\))/;
    const isNestController = /@(?:Controller|Resolver)\b/.test(content) && /@nestjs\/common/.test(content);
    const isServerAction = /^\s*['"]use server['"]/m.test(content);
    if (nodeContractRegex.test(content) || isNestController || isServerAction) {
      return { level: 'L2', id: 'SEM_NODE_CONTRACT', summary: `Node.js server routing/actions in ${norm}` };
    }

    // DB Schema (L2)
    const nodeDbRegex = /\bfrom\s+['"]drizzle-orm\/(?:pg-core|mysql-core|sqlite-core)['"]/;
    if (nodeDbRegex.test(content) || ext === '.prisma') {
      return { level: 'L2', id: 'SEM_NODE_PERSISTENCE', summary: `Node.js DB schema in ${norm}` };
    }
  }

  return null;
}

/**
 * Scans file content schema headers, config keys, and SQL DDL syntax (Layer 2).
 */
export function scanSchemaHeaders(filePath, content, { allChangedFiles = [] } = {}) {
  if (!content || typeof content !== 'string') return null;
  const norm = filePath.replace(/\\/g, '/');
  const base = path.basename(norm);
  const ext = path.extname(norm).toLowerCase();

  // 1. SQL DDL and Migration scripts
  if (ext === '.sql') {
    const hasDdl = /\b(?:CREATE\s+(?:TABLE|INDEX|VIEW)|ALTER\s+TABLE)\b/i.test(content);
    const hasDestructive = /\b(?:DROP\s+(?:TABLE|DATABASE)|TRUNCATE)\b/i.test(content);

    if (hasDestructive) {
      // Check paired down.sql with up.sql in the same PR
      const isDownSql = /\.down\.sql$/i.test(base);
      const counterpartUp = base.replace(/\.down\.sql$/i, '.up.sql');
      const hasPairedUp = isDownSql && allChangedFiles.some((f) => f.endsWith(counterpartUp));

      if (hasPairedUp) {
        return { level: 'L2', id: 'SEM_SQL_PAIRED_DOWN', summary: `Paired migration rollback script ${base}` };
      }
      return { level: 'L3', id: 'SEM_SQL_DESTRUCTIVE_DDL', summary: `Destructive SQL statement (DROP/TRUNCATE) in ${norm}`, mandatoryHumanReview: true };
    }

    if (hasDdl) {
      return { level: 'L2', id: 'SEM_SQL_DDL', summary: `SQL DDL migration statement in ${norm}` };
    }
  }

  // 2. Liquibase
  if (ext === '.xml' || ['.yml', '.yaml'].includes(ext)) {
    if (/databaseChangeLog/i.test(content)) {
      return { level: 'L2', id: 'SEM_LIQUIBASE', summary: `Liquibase database change log in ${norm}` };
    }
  }

  // 3. MyBatis XML
  if (ext === '.xml' && (/<mapper\s+namespace=/i.test(content) || /<!DOCTYPE\s+mapper/i.test(content))) {
    const hasWriteOrDdl = /<(?:insert|update|delete)\b/i.test(content) || /\b(?:CREATE|ALTER|DROP|TRUNCATE)\b/i.test(content);
    if (hasWriteOrDdl) {
      return { level: 'L2', id: 'SEM_MYBATIS_WRITE', summary: `MyBatis XML write/DDL mapping in ${norm}` };
    }
    // Pure select queries stay L1 routine
    return { level: 'L1', id: 'SEM_MYBATIS_SELECT', summary: `MyBatis XML pure select query in ${norm}` };
  }

  // 4. Cloud / K8s / Serverless / IaC
  if (base.toLowerCase() === 'chart.yaml' || base.toLowerCase() === 'chart.yml') {
    return { level: 'L2', id: 'SEM_HELM_CHART', summary: `Helm chart definition in ${norm}` };
  }
  if (ext === '.tf') {
    return { level: 'L2', id: 'SEM_TERRAFORM', summary: `Terraform infrastructure definition in ${norm}` };
  }
  if (['.yaml', '.yml'].includes(ext)) {
    if (/\bapiVersion:\s*[^\r\n]+/i.test(content) && /^[ \t]*kind:\s*(?:Deployment|StatefulSet|DaemonSet|Ingress|Role|ClusterRole|RoleBinding|Secret|Service)\b/m.test(content)) {
      return { level: 'L2', id: 'SEM_K8S_MANIFEST', summary: `Kubernetes workload/service manifest in ${norm}` };
    }
    if (/^[ \t]*edition:\s*[^\r\n]+/m.test(content) && /^[ \t]*services:\s*$/m.test(content)) {
      return { level: 'L2', id: 'SEM_SERVERLESS_DEVS', summary: `Serverless Devs application manifest in ${norm}` };
    }
    if (/openapi:\s*['"]?3\.|swagger:\s*['"]?2\./i.test(content)) {
      return { level: 'L2', id: 'SEM_OPENAPI_SPEC', summary: `OpenAPI specification document in ${norm}` };
    }
  }

  // 5. Core Configuration Keys
  if (['.properties', '.yaml', '.yml', '.json', '.toml'].includes(ext)) {
    // High-risk security config (L3)
    if (/(?:quarkus\.oidc\.|server\.ssl\.|spring\.security\.)/i.test(content)) {
      return { level: 'L3', id: 'SEM_CONFIG_SECURITY', summary: `Core security configuration keys in ${norm}`, mandatoryHumanReview: true };
    }
    // Architecture / Datasource config (L2)
    if (/(?:spring\.datasource\.|spring\.cloud\.nacos\.|dubbo\.|seata\.|quarkus\.datasource\.)/i.test(content)) {
      return { level: 'L2', id: 'SEM_CONFIG_ARCH', summary: `Core architectural datasource/registry config in ${norm}` };
    }
  }

  return null;
}

/**
 * Scans standard build manifests and supply chain configuration (Layer 3).
 */
export function scanToolchainManifests(filePath, content) {
  const norm = filePath.replace(/\\/g, '/');
  const base = path.basename(norm).toLowerCase();

  // Cloud pipeline
  if (/\.workflow\/.*\.ya?ml$/i.test(norm)) {
    return { level: 'L3', id: 'SEM_WORKFLOW_CI', summary: `CI workflow pipeline in ${norm}`, mandatoryHumanReview: true };
  }

  // Standard build tools
  const buildManifests = [
    'pom.xml', 'build.gradle', 'build.gradle.kts', 'settings.gradle', 'settings.gradle.kts',
    'libs.versions.toml', 'go.mod', 'go.work', 'pyproject.toml', 'cmakelists.txt'
  ];
  if (buildManifests.includes(base) || base.startsWith('requirements') && base.endsWith('.txt') || base.endsWith('.csproj') || base.endsWith('.proto')) {
    return { level: 'L2', id: 'SEM_BUILD_MANIFEST', summary: `Standard build toolchain manifest ${base}` };
  }

  // package.json supply chain vs metadata
  if (base === 'package.json' && content) {
    try {
      const parsed = JSON.parse(content);
      // If substantive keys are present (dependencies or scripts)
      if (parsed.dependencies || parsed.devDependencies || parsed.scripts || parsed.exports || parsed.main) {
        return { level: 'L2', id: 'SEM_PACKAGE_JSON', summary: `Node.js package.json dependency or script manifest` };
      }
    } catch {
      return { level: 'L2', id: 'SEM_PACKAGE_JSON', summary: `Node.js package.json manifest` };
    }
  }

  return null;
}

/**
 * Analyzes a changed file across all 3 static semantics layers.
 */
export function analyzeFileSemantics({ filePath, content, oldContent, allChangedFiles = [] } = {}) {
  // If file is generated code, exclude from risk escalation
  if (isGeneratedFile(filePath, content, oldContent)) {
    return { isGenerated: true, level: 'L1', mandatoryHumanReview: false, signals: [] };
  }

  const signals = [];
  let maxLevel = 'L1';
  let mandatoryReview = false;

  const checkSignal = (sig) => {
    if (!sig) return;
    signals.push(sig);
    if (sig.level === 'L3') {
      maxLevel = 'L3';
      if (sig.mandatoryHumanReview) mandatoryReview = true;
    } else if (sig.level === 'L2' && maxLevel !== 'L3') {
      maxLevel = 'L2';
    }
  };

  // Inspect current (head) content
  if (content) {
    checkSignal(scanImports(filePath, content));
    checkSignal(scanSchemaHeaders(filePath, content, { allChangedFiles }));
    checkSignal(scanToolchainManifests(filePath, content));
  }

  // Inspect old (baseRef) content (detects deletions of contracts, manifests, or security rules)
  if (oldContent && oldContent !== content) {
    checkSignal(scanImports(filePath, oldContent));
    checkSignal(scanSchemaHeaders(filePath, oldContent, { allChangedFiles }));
    checkSignal(scanToolchainManifests(filePath, oldContent));
  }

  return {
    isGenerated: false,
    level: maxLevel,
    mandatoryHumanReview: mandatoryReview,
    signals
  };
}

/**
 * Batches file reading and static semantics analysis for a set of changed files,
 * eliminating redundant disk I/O and git subprocess spawns across vectors.
 */
export function batchAnalyzeFileSemantics(changedFiles = [], { repoRoot = null, baseRef = null } = {}) {
  const cache = new Map();
  if (!Array.isArray(changedFiles) || changedFiles.length === 0) return cache;

  const substantive = changedFiles.filter((f) => !isTestOrDocFile(f));
  let baseFilesMap = new Map();
  if (repoRoot && baseRef && substantive.length > 0) {
    baseFilesMap = getBatchGitFiles(repoRoot, baseRef, substantive);
  }

  for (const f of changedFiles) {
    if (isTestOrDocFile(f)) {
      cache.set(f, {
        filePath: f,
        headContent: null,
        oldContent: null,
        isGenerated: false,
        level: 'L1',
        mandatoryHumanReview: false,
        signals: []
      });
      continue;
    }

    const fullPath = path.isAbsolute(f) ? f : (repoRoot ? path.join(repoRoot, f) : f);
    let headContent = null;
    if (fs.existsSync(fullPath)) {
      try {
        headContent = fs.readFileSync(fullPath, 'utf8');
      } catch { /* binary or unreadable */ }
    }

    const oldContent = baseFilesMap.get(f) || null;

    const sem = analyzeFileSemantics({
      filePath: f,
      content: headContent,
      oldContent,
      allChangedFiles: changedFiles
    });

    cache.set(f, {
      filePath: f,
      headContent,
      oldContent,
      ...sem
    });
  }

  return cache;
}

